UPDATE companies SET description='Rail Yard Studios operates from Nashville, Tennessee. Industrial designer and entrepreneur Robert Hendrick founded the company to complement the cyclical nature of the railroad contracting business he owned. The studio is owned by Hendrick along with Rob Humphreys, Rick Turner, and Jim "Pop" Hendrick, who serves as a mentor in the workshop.

The studio designs and builds custom furniture for home and office, including tables, desks, beds, coffee tables, wine racks, and gift items. Its signature material is reclaimed steel sourced from railroad renovation projects, paired with natural wood and authentic vintage materials. The team has developed proprietary historic-preservation methods to repurpose industrial rail sections into finished pieces. Master craftsman Ryan Galbreath manages the workshop, overseeing metalworking, woodworking, and the development of new fabrication techniques.

Rail Yard Studios serves residential and commercial clients, often collaborating with artists, designers, and architects on custom conference rooms, statement pieces, and full furnishings. The product line reflects Hendrick''s background in industrial design and his interests in cycling, history, and art.

The venture began as a way to stabilize revenue between railroad contracts, but its mission centers on sustainability and quality: each piece carries a narrative of the rail''s service history. The company emphasizes a direct hand-off from maker to client, with pride in craftsmanship and environmental footprint.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Furniture fabrication", "Metal reclamation and repurposing", "Woodworking", "Historic preservation techniques", "Sustainable material sourcing", "Custom conference room furniture", "Custom coffee tables, desks, beds, wine racks"], "industries": ["Residential furniture", "Commercial office furniture", "Custom furniture"], "materials": ["Reclaimed steel", "Natural wood", "Authentic vintage materials", "Railroad rail"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Reclaims railroad steel from industrial renovation jobs for furniture", "Proprietary historic-preservation methods for sustainability and quality", "Custom designs by industrial designer Robert Hendrick", "Collaboration with artists, designers, and architects", "Workshop led by master craftsman Ryan Galbreath"], "facts_used": ["Location: Nashville, Tennessee -> db", "Founder: Robert Hendrick -> /about-us", "Owners: Robert Hendrick, Rob Humphreys, Rick Turner, Jim ''Pop'' Hendrick -> /about-us", "Production manager: Ryan Galbreath -> /about-us", "Business origin: founded to round out cyclical railroad contracting business -> /about-us", "Products: custom furniture (tables, desks, beds, coffee tables, wine racks, gifts) -> /, /about-us", "Materials: reclaimed steel, natural wood, authentic vintage materials, railroad rail -> /, /about-us", "Processes: reclaiming steel from industrial jobs, repurposing, historic preservation methods, woodworking, metalworking -> /about-us", "Sustainability focus: sustainably sourced, historic preservation -> /", "Collaboration: with artists, designers, architects -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We make furniture, but we also build railroads.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='rail-yard-studios-custom-furniture-designers-and-builders' AND approved AND profile IS NULL;
